/**
 * The engine: one per process.
 */
public protocol FfiEngineProtocol: AnyObject, Sendable {
    
    func activateTab(id: UInt64) throws 
    
    func activeTab()  -> FfiTab?
    
    func addFavourite(path: String, index: UInt32?) throws 
    
    /**
     * The app is quitting: save the session and flush.
     */
    func appWillQuit() 
    
    func breadcrumbs(path: String)  -> [FfiCrumb]
    
    func clearFinishedOps() 
    
    /**
     * The core clipboard's paths (empty when nothing is copied).
     */
    func clipboardPaths()  -> [String]
    
    func closeOtherTabs(keep: UInt64) throws 
    
    func closeTab(id: UInt64) throws 
    
    func closeWindow(id: UInt64) throws 
    
    func commandKeys(command: String)  -> [String]
    
    /**
     * Every registered command with its current shortcut.
     */
    func commands()  -> [FfiCommandInfo]
    
    func complete(input: String, cursor: UInt32, cwd: String)  -> FfiCompletions
    
    /**
     * The context menu for a target. Reads Finder tags (an xattr) of the
     * target items for the Tags submenu.
     */
    func contextMenu(target: FfiMenuTarget, ctx: FfiMenuContext) throws  -> [FfiMenuItem]
    
    func copyPathAs(path: String, style: FfiPathStyle)  -> String
    
    /**
     * Creates a missing folder (through the queue) and shows it.
     */
    func createFolderAndGo(tab: UInt64, path: String) throws  -> FfiOutcome
    
    func dataDir()  -> String
    
    func deleteWorkspace(id: UInt64) throws 
    
    /**
     * Queues an operation (drag and drop).
     */
    func enqueue(req: FfiOpRequest) throws  -> Int64
    
    func exportKeymap()  -> String
    
    func exportSettings()  -> String
    
    func favourites()  -> [FfiFavourite]
    
    /**
     * Delivers held events now (tests and scripts).
     */
    func flushEvents() 
    
    func focusPane(window: UInt64, index: UInt32) throws 
    
    func frecent(query: String, limit: UInt32)  -> [FfiFrecentDir]
    
    /**
     * What a key press means; `None` means "not ours", let the focused
     * control handle it.
     */
    func handleKey(chord: FfiKeyChord, ctx: FfiInputContext)  -> FfiOutcome?
    
    /**
     * The overlay rows for held modifiers.
     */
    func heldShortcuts(mods: FfiMods, ctx: FfiInputContext)  -> FfiHeldShortcuts?
    
    /**
     * Records a command run outside `perform`; may return a hint.
     */
    func hintFor(command: String, via: FfiVia)  -> FfiHint?
    
    func home()  -> String
    
    /**
     * Returns warnings.
     */
    func importKeymap(json: String) throws  -> [String]
    
    func importSettings(json: String) throws 
    
    /**
     * Imports zoxide's database once; returns (added, merged).
     */
    func importZoxide(dbPath: String?) throws  -> [UInt32]
    
    /**
     * Ops left unfinished by an earlier run, offered for resume. Reads the journal.
     */
    func interruptedOps() throws  -> [FfiOpStatus]
    
    func keymapConflicts()  -> [String]
    
    func menuAdd(kind: FfiMenuKind, entry: String, after: String?) throws 
    
    func menuChoices(kind: FfiMenuKind)  -> [FfiMenuEntry]
    
    func menuEntries(kind: FfiMenuKind)  -> [FfiMenuEntry]
    
    func menuMove(kind: FfiMenuKind, entry: String, after: String?) throws 
    
