        FfiConverterTypeFfiEngineConfig_lower(config),
        FfiConverterTypeFfiEventSink_lower(sink),uniffiCallStatus
    )
}
    self.init(unsafeFromHandle: handle)
}

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_fstudio_ffi_fn_free_ffiengine(handle, $0) }
    }

    

    
