/**
 * One tab: a location, its history, view state, selection and listing.
 */
public protocol FfiTabProtocol: AnyObject, Sendable {
    
    func back() throws  -> FfiOutcome
    
    /**
     * The address bar's crumbs for this tab's folder.
     */
    func breadcrumbs()  -> [FfiCrumb]
    
    /**
     * Can go back / forward.
     */
