public struct FfiConverterTypeFfiTab: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = FfiTab

    public static func lift(_ handle: UInt64) throws -> FfiTab {
        return FfiTab(unsafeFromHandle: handle)
    }

    public static func lower(_ value: FfiTab) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiTab {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: FfiTab, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


