/**
 * Why a listing changed.
 */

public enum FfiChangeKind: Equatable, Hashable {
    
    case partial
    case sorted
    case patched
    case resorted
    case error





}

#if compiler(>=6)
extension FfiChangeKind: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiChangeKind: FfiConverterRustBuffer {
    typealias SwiftType = FfiChangeKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiChangeKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .partial
        
        case 2: return .sorted
        
        case 3: return .patched
        
        case 4: return .resorted
        
        case 5: return .error
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiChangeKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .partial:
            writeInt(&buf, Int32(1))
        
        
        case .sorted:
            writeInt(&buf, Int32(2))
        
        
        case .patched:
            writeInt(&buf, Int32(3))
        
        
        case .resorted:
            writeInt(&buf, Int32(4))
        
        
        case .error:
            writeInt(&buf, Int32(5))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFfiChangeKind_lift(_ buf: RustBuffer) throws -> FfiChangeKind {
    return try FfiConverterTypeFfiChangeKind.lift(buf)
}

