    return FfiConverterTypeFfiChangeKind.lower(value)
}



/**
 * A command's argument.
 */

public enum FfiCommandArg: Equatable, Hashable {
    
    case path(path: String
    )
    case index(index: UInt32
    )
    case viewMode(mode: FfiViewMode
    )
    /**
     * One character.
     */
    case char(value: String
    )
    case confirm
    /**
     * The user said yes to the core's confirmation question.
     */
    case confirmed
    case text(text: String
    )





}

#if compiler(>=6)
extension FfiCommandArg: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiCommandArg: FfiConverterRustBuffer {
    typealias SwiftType = FfiCommandArg

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiCommandArg {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .path(path: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .index(index: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 3: return .viewMode(mode: try FfiConverterTypeFfiViewMode.read(from: &buf)
        )
        
        case 4: return .char(value: try FfiConverterString.read(from: &buf)
        )
        
