 * Something the shell should react to. Delivered on one core thread, in
 * order; the Swift side hops to the main actor.
 */

public enum FfiEvent: Equatable, Hashable {
    
    case listingChanged(tab: UInt64, version: UInt64, kind: FfiChangeKind
    )
    case selectionChanged(tab: UInt64, count: UInt32, cursor: UInt32?
    )
    /**
     * Re-read the workspace state.
     */
    case tabsChanged
    case opProgress(ops: [FfiOpStatus]
    )
    case opConflict(op: Int64, conflict: FfiConflict
    )
    case opFailed(op: Int64, path: String, error: String
    )
    case opFinished(op: Int64, report: FfiOpReport
    )
    case undoChanged(state: FfiUndoState
    )
    case volumesChanged(volumes: [FfiVolume]
    )
    case hint(hint: FfiHint
    )
    case settingsChanged
    case favouritesChanged





}

#if compiler(>=6)
extension FfiEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiEvent: FfiConverterRustBuffer {
    typealias SwiftType = FfiEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .listingChanged(tab: try FfiConverterUInt64.read(from: &buf), version: try FfiConverterUInt64.read(from: &buf), kind: try FfiConverterTypeFfiChangeKind.read(from: &buf)
        )
        
        case 2: return .selectionChanged(tab: try FfiConverterUInt64.read(from: &buf), count: try FfiConverterUInt32.read(from: &buf), cursor: try FfiConverterOptionUInt32.read(from: &buf)
        )
        
        case 3: return .tabsChanged
        
        case 4: return .opProgress(ops: try FfiConverterSequenceTypeFfiOpStatus.read(from: &buf)
        )
        
        case 5: return .opConflict(op: try FfiConverterInt64.read(from: &buf), conflict: try FfiConverterTypeFfiConflict.read(from: &buf)
        )
        
        case 6: return .opFailed(op: try FfiConverterInt64.read(from: &buf), path: try FfiConverterString.read(from: &buf), error: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .opFinished(op: try FfiConverterInt64.read(from: &buf), report: try FfiConverterTypeFfiOpReport.read(from: &buf)
        )
        
        case 8: return .undoChanged(state: try FfiConverterTypeFfiUndoState.read(from: &buf)
        )
        
        case 9: return .volumesChanged(volumes: try FfiConverterSequenceTypeFfiVolume.read(from: &buf)
        )
        
        case 10: return .hint(hint: try FfiConverterTypeFfiHint.read(from: &buf)
        )
        
        case 11: return .settingsChanged
        
        case 12: return .favouritesChanged
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .listingChanged(tab,version,kind):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(tab, into: &buf)
            FfiConverterUInt64.write(version, into: &buf)
            FfiConverterTypeFfiChangeKind.write(kind, into: &buf)
            
        
        case let .selectionChanged(tab,count,cursor):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(tab, into: &buf)
            FfiConverterUInt32.write(count, into: &buf)
            FfiConverterOptionUInt32.write(cursor, into: &buf)
            
        
        case .tabsChanged:
            writeInt(&buf, Int32(3))
        
        
        case let .opProgress(ops):
            writeInt(&buf, Int32(4))
            FfiConverterSequenceTypeFfiOpStatus.write(ops, into: &buf)
            
        
        case let .opConflict(op,conflict):
            writeInt(&buf, Int32(5))
            FfiConverterInt64.write(op, into: &buf)
            FfiConverterTypeFfiConflict.write(conflict, into: &buf)
            
        
        case let .opFailed(op,path,error):
            writeInt(&buf, Int32(6))
            FfiConverterInt64.write(op, into: &buf)
            FfiConverterString.write(path, into: &buf)
            FfiConverterString.write(error, into: &buf)
            
        
        case let .opFinished(op,report):
            writeInt(&buf, Int32(7))
            FfiConverterInt64.write(op, into: &buf)
            FfiConverterTypeFfiOpReport.write(report, into: &buf)
            
        
        case let .undoChanged(state):
            writeInt(&buf, Int32(8))
            FfiConverterTypeFfiUndoState.write(state, into: &buf)
            
        
        case let .volumesChanged(volumes):
            writeInt(&buf, Int32(9))
            FfiConverterSequenceTypeFfiVolume.write(volumes, into: &buf)
            
        
        case let .hint(hint):
            writeInt(&buf, Int32(10))
            FfiConverterTypeFfiHint.write(hint, into: &buf)
            
        
        case .settingsChanged:
            writeInt(&buf, Int32(11))
        
        
        case .favouritesChanged:
            writeInt(&buf, Int32(12))
        
        }
    }
}


